SELECT * FROM ai_plan_briefs
 WHERE conversation_id = #{conversationId}
   AND user_id = #{userId}

SELECT * FROM ai_plan_briefs
 WHERE brief_id = #{briefId}
   AND user_id = #{userId}

SELECT * FROM ai_plan_briefs
 WHERE user_id = #{userId}
 ORDER BY updated_at DESC, brief_id DESC
 LIMIT #{limit}

