UPDATE ai_plan_briefs
   SET items   = #{items},
       status  = #{status},
       version = version + 1
 WHERE brief_id = #{briefId}
   AND user_id  = #{userId}
   AND version  = #{expectedVersion}

UPDATE ai_plan_briefs
   SET last_proposal_id = #{lastProposalId}
 WHERE brief_id = #{briefId}
   AND user_id  = #{userId}
